import pandas as pd
import matplotlib.pyplot as plt
import numpy as np

# Load dataset generated by C++ main.cpp
data = pd.read_csv("signals.csv")

# Compute absolute errors relative to benchmark S0 (long double truth)
data['Err_S1'] = np.abs(data['S1'] - data['S0'])
data['Err_S2'] = np.abs(data['S2'] - data['S0'])
data['Err_S3'] = np.abs(data['S3'] - data['S0'])
data['Err_S4'] = np.abs(data['S4'] - data['S0'])

# -----------------------------------------------------------------------------
# Global Binning Setup for Error PDFs
# -----------------------------------------------------------------------------
all_errors = np.concatenate([
    data['Err_S1'][data['Err_S1'] > 0],
    data['Err_S2'][data['Err_S2'] > 0],
    data['Err_S3'][data['Err_S3'] > 0],
    data['Err_S4'][data['Err_S4'] > 0]
])

min_exponent = np.floor(np.log10(all_errors.min())) if len(all_errors) > 0 else -16
max_exponent = np.ceil(np.log10(all_errors.max())) if len(all_errors) > 0 else -3
bins = np.logspace(min_exponent, max_exponent, 120)

configs = [
    ('Err_S1', 'S1: True MA (Neumaier O(NW))', 'blue', '--'),
    ('Err_S2', 'S2: True MA (Naive O(NW))', 'orange', ':'),
    ('Err_S3', 'S3: Running MA (Naive Float O(N))', 'green', '-.'),
    ('Err_S4', 'S4: Running MA (sigutils O(N))', 'red', '-')
]

# Create layout: 1 top panel for signals + 4 bottom panels for error PDFs
fig = plt.figure(figsize=(14, 16))
gs = fig.add_gridspec(5, 1, height_ratios=[2, 1, 1, 1, 1])

ax_sig = fig.add_subplot(gs[0])
axes_pdf = [fig.add_subplot(gs[i], sharex=None) for i in range(1, 5)]

# Share X-axis across the 4 PDF subplots
for i in range(1, 4):
    axes_pdf[i].sharex(axes_pdf[0])

# -----------------------------------------------------------------------------
# Panel 0: Full Signal Overlay (Plots ALL datapoints)
# -----------------------------------------------------------------------------
# Decimate visually if dataset exceeds 20,000 points to keep plotting fast
stride = max(1, len(data) // 20000)
data_plot = data.iloc[::stride]

ax_sig.plot(data_plot['sample_index'], data_plot['S'], color='gray', alpha=0.3, label='Raw Signal S (Phase-Centered)')
ax_sig.plot(data_plot['sample_index'], data_plot['S0'], label='S0: Ground Truth (long double)', color='black', linewidth=1.8)
ax_sig.plot(data_plot['sample_index'], data_plot['S1'], '--', label='S1: True MA (Neumaier O(NW))', alpha=0.8)
ax_sig.plot(data_plot['sample_index'], data_plot['S2'], ':', label='S2: True MA (Naive O(NW))', alpha=0.8)
ax_sig.plot(data_plot['sample_index'], data_plot['S3'], '-.', label='S3: Running MA (Naive Float O(N))', alpha=0.8)
ax_sig.plot(data_plot['sample_index'], data_plot['S4'], '-', label='S4: Running MA (sigutils O(N))', linewidth=1.2)

ax_sig.set_title(f"Full Signal Comparison ({len(data):,} Samples Total)", fontsize=14, fontweight='bold')
ax_sig.set_xlabel("Sample Index", fontsize=11)
ax_sig.set_ylabel("Amplitude", fontsize=11)
ax_sig.grid(True, linestyle='--', alpha=0.6)
ax_sig.legend(loc='upper right', framealpha=0.9, fontsize=9)

# -----------------------------------------------------------------------------
# Panels 1-4: Separate 4x1 Error Probability Density Functions (PDF)
# -----------------------------------------------------------------------------
for ax, (err_col, label, color, linestyle) in zip(axes_pdf, configs):
    err_values = data[err_col].values
    err_values = err_values[err_values > 0]
    
    if len(err_values) > 0:
        ax.hist(
            err_values, 
            bins=bins, 
            density=True, 
            histtype='stepfilled', 
            alpha=0.3, 
            color=color, 
            edgecolor=color, 
            linewidth=1.2,
            label=f"{label} (N={len(err_values):,})"
        )
        ax.hist(
            err_values, 
            bins=bins, 
            density=True, 
            histtype='step', 
            color=color, 
            linewidth=1.8, 
            linestyle=linestyle
        )

    ax.set_xscale('log')
    ax.set_yscale('log')
    ax.grid(True, which="both", linestyle='--', alpha=0.5)
    ax.legend(loc='upper right', framealpha=0.9, fontsize=9)
    ax.set_ylabel("Probability Density", fontsize=10)

axes_pdf[-1].set_xlabel("Absolute Error $|S_i - S_0|$ (Log Scale)", fontsize=12)
axes_pdf[0].set_title("Individual Error Probability Density Functions (PDF)", fontsize=13, fontweight='bold')

plt.tight_layout()
plt.savefig("full_benchmark_plot.png", dpi=300)
plt.show()